/* ❌ OLD: Global z-index escalation. Every new overlay needs a higher
   number to beat the last one, and any ancestor with a stacking
   context traps the whole subtree — so 9999 often does nothing. */

.modal {
  position: fixed;
  z-index: 9999; /* ❌ OLD: arbitrary arms race number */
}

.tooltip {
  position: absolute;
  z-index: 10000; /* ❌ OLD: must beat the modal everywhere it appears */
}

/* The moment a parent creates a stacking context (transform,
   opacity, filter), these numbers compare only inside that parent —
   the modal can silently appear UNDER unrelated fixed headers. */

/* ✅ NEW: isolation: isolate creates a fresh stacking context on the
   root of each widget, so internal z-index battles stay scoped and
   never leak to siblings. No global numbers required. */

.overlay-root {
  isolation: isolate; /* ✅ NEW: seals this subtree's stacking order */
}

.modal {
  position: fixed;
  z-index: 10; /* ✅ NEW: small, local numbers — only compete inside the root */
}

.tooltip {
  position: absolute;
  z-index: 20; /* ✅ NEW: beats the modal within the same isolated root */
}

/* Both the modal and the tooltip are compared only inside
   .overlay-root; unrelated page content cannot interleave with them. */
